for lang,index in [('de_de',0),('en_us',1)]:
    path=RES/f'assets/thedarkdimensions/lang/{lang}.json';data=json.loads(path.read_text(encoding='utf-8'))
    for row in ROWS:
        for choice,offset in [(1,1),(2,5)]:
            key=f'mastery.thedarkdimensions.{row[0].lower()}.{choice}'
            data[key]=row[offset+index];data[key+'.desc']=row[offset+2+index]
    data.update({key:pair[index] for key,pair in EXTRA.items()})
    path.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
